use std::{
    io::{Cursor, Error},
    path::Path,
};

use crate::tls::Error::NoCertificatesFound;

use super::error::Result;
use local_ip_address::list_afinet_netifas;
use rcgen::generate_simple_self_signed;
use rustls_pemfile::certs;
use sha2::{Digest, Sha256};
use tokio::{fs, io};

/// A loaded TLS identity consisting of a self-signed certificate and its private key,
/// both stored in PEM format.
///
/// The certificate is generated by [`rcgen`] and covers standard loopback Subject Alternative Names
/// (`localhost`, `127.0.0.1`, and `0.0.0.0`) alongside dynamically discovered LAN IP addresses
/// and optional mDNS local domains (e.g. `<hostname>.local`), making it suitable for local network
/// deployments without certificate name mismatch warnings.
///
/// Use [`Identity::load_or_create`] at server startup to either load an existing identity
/// from disk or generate a fresh one. The resulting identity is then passed to the
/// [`crate::tls`] module and the admin CLI for TOFU device pairing.
pub struct Identity {
    /// The certificate in PEM format, including the `-----BEGIN CERTIFICATE-----` header.
    pub cert_pem: String,
    /// The private key in PEM format, including the `-----BEGIN PRIVATE KEY-----` header.
    pub key_pem: String,
}

impl Identity {
    /// Loads an existing TLS identity from `<vault_path>/tls/`, or generates a new one with extra SANs.
    ///
    /// If `cert.pem` and `key.pem` are both present under `<vault_path>/tls/`, they are
    /// read from disk and returned as-is. If either file is missing, a fresh self-signed
    /// X.509 certificate is generated via [`rcgen`] covering standard loopback names plus any
    /// `extra_sans` provided (such as LAN IP addresses and `<hostname>.local`), and persisted
    /// to disk.
    ///
    /// # Arguments
    ///
    /// * `vault_path` - Root directory of the server vault where the `tls/` subdirectory resides.
    /// * `extra_sans` - Additional Subject Alternative Names (IP addresses, hostnames) to include in the certificate.
    ///
    /// # Errors
    ///
    /// - Returns [`super::Error::Io`] if the `tls/` directory cannot be created, or if the PEM files cannot be read or written.
    /// - Returns [`super::Error::CertificateGen`] if `rcgen` fails to generate a valid certificate.
    pub async fn load_or_create<P, S>(
        vault_path: P,
        extra_sans: &[S],
    ) -> Result<Self>
    where
        P: AsRef<Path> + Send,
        S: AsRef<str> + Sync,
    {
        let tls_dir = vault_path.as_ref().join("tls");
        let cert_path = tls_dir.join("cert.pem");
        let key_path = tls_dir.join("key.pem");

        if cert_path.exists() && key_path.exists() {
            Self::load(&cert_path, &key_path).await
        } else {
            fs::create_dir_all(tls_dir).await?;
            Self::create(&cert_path, &key_path, extra_sans).await
        }
    }

    /// Loads a TLS identity by reading PEM files from the given paths.
    ///
    /// Both files are read in their entirety into memory. No validation of the certificate
    /// or key contents is performed at this stage; errors will surface later when the
    /// identity is used to configure the TLS acceptor.
    ///
    /// # Arguments
    ///
    /// * `cert_path` - Path to the PEM-encoded X.509 certificate file.
    /// * `key_path` - Path to the PEM-encoded private key file.
    ///
    /// # Errors
    ///
    /// Returns [`super::Error::Io`] if either file cannot be read from disk.
    pub async fn load<P>(cert_path: P, key_path: P) -> Result<Self>
    where
        P: AsRef<Path> + Send,
    {
        let cert_pem = fs::read_to_string(cert_path.as_ref()).await?;
        let key_pem = fs::read_to_string(key_path.as_ref()).await?;

        Ok(Self { cert_pem, key_pem })
    }

    /// Generates a fresh self-signed identity with the given extra SANs and writes PEM files to disk.
    ///
    /// # Arguments
    ///
    /// * `cert_path` - Destination path for writing the certificate PEM.
    /// * `key_path` - Destination path for writing the private key PEM.
    /// * `extra_sans` - Additional Subject Alternative Names to embed in the certificate.
    ///
    /// # Errors
    ///
    /// - Returns [`super::Error::CertificateGen`] if certificate generation fails.
    /// - Returns [`super::Error::Io`] if writing either PEM file to disk fails.
    async fn create<P, S>(
        cert_path: P,
        key_path: P,
        extra_sans: &[S],
    ) -> Result<Self>
    where
        P: AsRef<Path> + Send,
        S: AsRef<str> + Sync,
    {
        let identity = Self::forge(extra_sans)?;

        fs::write(cert_path, &identity.cert_pem).await?;
        fs::write(key_path, &identity.key_pem).await?;

        Ok(identity)
    }

    /// Generates a new self-signed certificate in memory with deduplicated Subject Alternative Names.
    ///
    /// Automatically seeds the SAN list with `localhost`, `127.0.0.1`, and `0.0.0.0`, then
    /// appends each non-empty entry from `extra_sans` (trimming whitespace and skipping duplicates).
    ///
    /// # Arguments
    ///
    /// * `extra_sans` - Extra IP addresses or hostnames to embed in the certificate.
    ///
    /// # Errors
    ///
    /// Returns [`super::Error::CertificateGen`] if `rcgen` fails to generate the certificate and signing key.
    fn forge<S>(extra_sans: &[S]) -> Result<Self>
    where
        S: AsRef<str>,
    {
        let mut sans = vec![
            "localhost".to_string(),
            "127.0.0.1".to_string(),
            "0.0.0.0".to_string(),
        ];

        for san in extra_sans {
            let s = san.as_ref().trim();
            if s.is_empty() || sans.iter().any(|existing| existing == s) {
                continue;
            }
            sans.push(s.to_string());
        }

        let certified_key = generate_simple_self_signed(sans)?;

        Ok(Self {
            cert_pem: certified_key.cert.pem(),
            key_pem: certified_key.signing_key.serialize_pem(),
        })
    }

    /// Computes the SHA-256 fingerprint of the certificate and returns it as a hex string.
    ///
    /// The fingerprint is computed over the DER-encoded form of the certificate, which is
    /// the standard representation used when displaying fingerprints for manual verification
    /// (e.g., in browser certificate dialogs).
    ///
    /// # Errors
    ///
    /// Returns [`super::Error::Io`] if the PEM data does not contain a valid DER certificate block.
    pub fn fingerprint(&self) -> Result<String> {
        let mut reader = Cursor::new(self.cert_pem.as_bytes());
        let mut cert_iter = certs(&mut reader);

        let der = cert_iter.next().ok_or_else(|| {
            Error::new(
                io::ErrorKind::InvalidData,
                "No certificate found in PEM",
            )
        })??;

        let mut hasher = Sha256::new();
        hasher.update(der.as_ref());
        let result = hasher.finalize();

        let hex_array: Vec<String> =
            result.iter().map(|b| format!("{b:02x}")).collect();
        Ok(hex_array.join(""))
    }

    /// Computes the raw 32-byte SHA-256 fingerprint of the certificate.
    ///
    /// Returns the fingerprint as a fixed-size byte array rather than a hex string.
    /// This form is used by the admin CLI to derive the BIP-39 verification mnemonic
    /// and to encode the certificate fingerprint into a QR code for TOFU device pairing.
    ///
    /// # Errors
    ///
    /// Returns [`super::Error::NoCertificatesFound`] if the PEM data does not contain a valid
    /// DER certificate block. Returns [`super::Error::Io`] if the DER block cannot be parsed.
    pub fn fingerprint_raw(&self) -> Result<[u8; 32]> {
        let mut reader = Cursor::new(self.cert_pem.as_bytes());
        let mut cert_iter = rustls_pemfile::certs(&mut reader);

        let der = cert_iter.next().ok_or(NoCertificatesFound)??;

        let mut hasher = Sha256::new();
        hasher.update(der.as_ref());

        Ok(hasher.finalize().into())
    }
}

/// Discovers all active, non-loopback IP addresses across all host network interfaces.
///
/// Iterates over system network interfaces using [`local_ip_address::list_afinet_netifas`],
/// filters out loopback addresses (`127.0.0.1`, `::1`), and deduplicates the results.
///
/// In self-hosted setups where the server does not have a public DNS hostname, clients often
/// connect directly using LAN IP addresses (e.g. `https://192.168.1.50:23342`). Embedding these
/// IPs as Subject Alternative Names (SANs) in the self-signed certificate is essential to prevent
/// TLS connection failures (`CertNotValidForName`) on modern TLS clients.
#[must_use]
pub fn lan_ips() -> Vec<String> {
    let mut ips = Vec::new();
    if let Ok(interfaces) = list_afinet_netifas() {
        for (_name, ip) in interfaces {
            if !ip.is_loopback() {
                let s = ip.to_string();
                if !ips.contains(&s) {
                    ips.push(s);
                }
            }
        }
    }
    ips
}
